# RLE constants

RLE_MIN_RUN = 3   # Minimum run length for compression
RLE_MAX_RUN = 127 # Maximum encoded run length
RLE_LIT_MAX = 126 # Maximum literal block length
RLE_FLG_RUN = 128 # High-bit marker for run blocks


# Worst-case compressed buffer size
RLE_BUF_SIZE = lambda sz: (
    (((sz + (RLE_LIT_MAX - 1)) // RLE_LIT_MAX)
    * RLE_MAX_RUN) + RLE_MIN_RUN
)



