ELF_FILE_MIN_SIZE = 256       # 256 B
ELF_FILE_MAX_SIZE = 256 << 20 # 256 MiB

ELFMAG      = b'\x7FELF'
ELFCLASS64  = 2
ELFDATA2LSB = 1
ET_EXEC     = 2
